import{c as t,Q as o,j as a,m as d}from"./chunks/framework.BOkOGOZz.js";const p=JSON.parse('{"title":"Search","description":"","frontmatter":{},"headers":[],"relativePath":"guide/using-librislog/search.md","filePath":"guide/using-librislog/search.md","lastUpdated":1787719464000}'),s={name:"guide/using-librislog/search.md"};function i(r,e,c,n,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h1><p>The search box on the <strong>Dashboard</strong>, <strong>Library</strong>, and dedicated <code>/search</code> page supports plain-text matching as well as field-specific and negated queries.</p><h2 id="field-prefixes" tabindex="-1">Field prefixes <a class="header-anchor" href="#field-prefixes" aria-label="Permalink to &quot;Field prefixes&quot;">​</a></h2><p>Use <code>&lt;field&gt;:&lt;value&gt;</code> to search in a single field. The field prefixes are always in <strong>English</strong>, regardless of the UI language.</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Field</th><th>Example</th></tr></thead><tbody><tr><td><code>author</code></td><td>Author(s)</td><td><code>author:Murakami</code></td></tr><tr><td><code>title</code></td><td>Title</td><td><code>title:&quot;The Hobbit&quot;</code></td></tr><tr><td><code>publisher</code></td><td>Publisher</td><td><code>publisher:Penguin</code></td></tr><tr><td><code>language</code></td><td>Language</td><td><code>language:Japanese</code></td></tr><tr><td><code>tag</code></td><td>Tag name</td><td><code>tag:fantasy</code></td></tr><tr><td><code>possession</code></td><td>Possession status</td><td><code>possession:owned</code></td></tr><tr><td><code>notes</code></td><td>Private notes</td><td><code>notes:&quot;to reread&quot;</code></td></tr><tr><td><code>description</code></td><td>Blurb / description</td><td><code>description:&quot;middle earth&quot;</code></td></tr></tbody></table><p>Use quotes for values that contain spaces: <code>title:&quot;The Silmarillion&quot;</code>.</p><p>The <code>author:</code> prefix matches <strong>any</strong> author assigned to a book — a book with multiple authors matches if any of them contains the search value.</p><h3 id="possession-values" tabindex="-1">Possession values <a class="header-anchor" href="#possession-values" aria-label="Permalink to &quot;Possession values&quot;">​</a></h3><p>The <code>possession</code> prefix matches the exact possession status. Accepted values include:</p><ul><li><code>to_acquire</code> (or <code>to acquire</code>)</li><li><code>owned</code></li><li><code>borrowed</code></li><li><code>digital</code></li></ul><p>Example: <code>possession:&quot;to acquire&quot;</code> shows books you want to buy.</p><h2 id="negation" tabindex="-1">Negation <a class="header-anchor" href="#negation" aria-label="Permalink to &quot;Negation&quot;">​</a></h2><p>Prefix a term with <code>-</code> to exclude matches.</p><ul><li><code>-author:Rowling</code></li><li><code>-tag:horror</code></li><li><code>Haushofer -&quot;Die Wand&quot;</code></li></ul><h2 id="combining-terms" tabindex="-1">Combining terms <a class="header-anchor" href="#combining-terms" aria-label="Permalink to &quot;Combining terms&quot;">​</a></h2><p>Separate terms with spaces. All terms are combined with <strong>AND</strong>.</p><ul><li><code>author:Murakami -title:Norwegian</code> — Murakami books except those whose title contains &quot;Norwegian&quot;</li><li><code>tag:fantasy possession:owned</code> — owned fantasy books</li></ul><h2 id="plain-text" tabindex="-1">Plain text <a class="header-anchor" href="#plain-text" aria-label="Permalink to &quot;Plain text&quot;">​</a></h2><p>An unprefixed phrase searches across title, author, publisher, language, notes, description, and tags. It is matched as a phrase, not as individual words.</p><ul><li><code>Marlen Haushofer</code> — matches the exact phrase across the supported fields</li><li><code>Haushofer -Wand</code> — matches &quot;Haushofer&quot; but excludes books whose fields contain &quot;Wand&quot;</li></ul><h2 id="quick-reference-in-the-app" tabindex="-1">Quick reference in the app <a class="header-anchor" href="#quick-reference-in-the-app" aria-label="Permalink to &quot;Quick reference in the app&quot;">​</a></h2><p>Click the <strong>?</strong> icon next to any search input to open a quick-reference card with the available prefixes and examples.</p>',22)])])}const g=t(s,[["render",i]]);export{p as __pageData,g as default};
